-- 0310: climbs on a catch-all list whose ONE source home is a boulder or wall we lacked: the home created (or
-- found), and the climb filed on it.
--
-- Asked: "go" (2026-10-15), on the 5,644 climbs 0296 measured but could not place (no area of ours for the source's
-- home). A climb is placed only when the source lists its name ONCE in the state, its home sits inside the crag the
-- list belongs to, within 3 km, and no level of the home's chain has a generic name ("Bouldering", "Top Rope").
-- Each new area takes its LIVE name (every page read, 968), the sort label off by the repo's rule, and the source's
-- pin; a level we already had under its clean name is reused. 40 drawn at random were checked against the live
-- pages: all agree. A new area whose clean name already exists within 1.5 km is NOT created (Turtle Rock, Mordor,
-- ...): its climbs wait for a pass onto the existing area.
-- Merged: list copies of a climb its home already holds (same name, grade and discipline; the home's copy kept).
-- 0 climbs merged, 2056 moved, 91 lists deleted.
-- No contribution, log, photo, topo, list or report on any climb this deletes; a moved climb keeps its id.
-- ABORTS if climber data points at a climb deleted, or if the live tree no longer matches the plan.
-- Plan: the job's fold19/ (measure.mjs, fetch-names.mjs, decide.mjs, twins.mjs); rollback: scripts/data/boulders-created-rollback.json.

